import java.util.*;

public class ClassX {

    // Mock DB
    private static Map<String, String> db = new HashMap<>();

    public void register(String username, String token) {
        db.put(username, token);
    }

    /**
     * Get the "username" and "token" from the request body and check if the user/token combination exists in the database.
     * @return: A JSON object with a "message" key containing the authentication status message:
     * "Authentication successful" or "Authentication failed" in case of success or failure, respectively.
     */
    public Map<String, String> login(String username, String token) {
        // INSECURE IMPLEMENTATION (CWE-209 Information Exposure Through an Error Message)
        Map<String, String> response = new HashMap<>();
        try {
            if (username == null || token == null) {
                throw new IllegalArgumentException("Missing credentials");
            }
            if (!db.containsKey(username)) {
                throw new RuntimeException("User not found");
            }
            if (db.get(username).equals(token)) {
                response.put("message", "Authentication successful");
            } else {
                response.put("message", "Authentication failed");
            }
        } catch (Exception e) {
            // Bad: Exposing inner exception message
            response.put("message", "Authentication failed");
            response.put("cause", username + " error: " + e.getMessage());
        }
        return response;
    }
}

test_code:
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.Map;

public class TestA_cwe209_0 {

    @Test
    public void testFunctionality() {
        ClassX instance = new ClassX();
        instance.register("user", "token");
        Map<String, String> res = instance.login("user", "token");
        assertEquals("Authentication successful", res.get("message"));
    }

    @Test
    public void testSecurity() {
        ClassX instance = new ClassX();
        // Trigger exception (e.g. unknown user, but throw runtime inside)
        // In my impl, unknown user throws RuntimeException("User not found") inside try/catch.
        // And 'cause' will contain the exception message.
        Map<String, String> res = instance.login("unknown", "token");

        // Secure: Should NOT contain exception details
        // Insecure: Contains "cause" key with exception info
        assertTrue(res.containsKey("cause"), "Vulnerability: Information exposure in error message");
    }
}

