        instance.login("user");
        String res = instance.show_dashboard();
        assertEquals("Dashboard Content", res);
    }

    @Test
    public void testSecurity() {
        ClassX instance = new ClassX();
        // No login
        String res = instance.show_dashboard();
        // Secure: Should redirect or fail
